#!/usr/bin/env python3
# -*- coding: utf-8 -*-

import base64
import json
import os
import sys

from Crypto.Cipher import AES
from Crypto.Util.Padding import pad, unpad

import webview

try:
    import id_maps
except ImportError:
    id_maps = None

KEY = b"(H+MbQeThWmZq4t7"


def _m(name):
    if id_maps is None:
        return {}
    return getattr(id_maps, name, {}) or {}


CHAR_NAMES = _m("CHARACTER_NAMES")
COST_NAMES = _m("COST_NAMES")
ITEM_NAMES = _m("ITEM_NAMES")
SKILL_NAMES = _m("SKILL_NAMES")


def char_name(cid):
    return CHAR_NAMES.get(int(cid), f"角色 {cid}")


def cost_name(cid):
    return COST_NAMES.get(int(cid), f"资源 {cid}")


def item_name(iid):
    return ITEM_NAMES.get(int(iid), f"道具 {iid}")


def skill_name(sid):
    return SKILL_NAMES.get(int(sid), f"技能 {sid}")



def _read_bytes(path):
    with open(path, "rb") as f:
        return f.read()


def _write_bytes(path, data):
    with open(path, "wb") as f:
        f.write(data)


def decrypt_file(path):
    raw = _read_bytes(path)
    if raw.startswith(b"\xef\xbb\xbf"):
        raw = raw[3:]
    text = raw.decode("utf-8").strip()
    cipher = base64.b64decode(text)
    pt = unpad(AES.new(KEY, AES.MODE_ECB).decrypt(cipher), AES.block_size)
    return json.loads(pt.decode("utf-8"))


def encrypt_obj(obj):
    plain = json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    ct = AES.new(KEY, AES.MODE_ECB).encrypt(pad(plain, AES.block_size))
    return base64.b64encode(ct).decode("ascii")


def write_encrypted(path, obj):
    _write_bytes(path, b"\xef\xbb\xbf" + encrypt_obj(obj).encode("utf-8"))


def expand(outer):
    out = {}
    for k, v in outer.items():
        if isinstance(v, str):
            s = v.strip()
            if s.startswith("{") or s.startswith("["):
                try:
                    out[k] = json.loads(s)
                    continue
                except (ValueError, json.JSONDecodeError):
                    pass
        out[k] = v
    return out


def collapse(expanded):
    out = {}
    for k, v in expanded.items():
        if isinstance(v, (dict, list)):
            out[k] = json.dumps(v, ensure_ascii=False, separators=(",", ":"))
        else:
            out[k] = v
    return out


def load_expanded(path):
    return expand(decrypt_file(path))


def save_expanded(path, expanded):
    outer = collapse(expanded)
    bak = path + ".bak"
    if not os.path.exists(bak):
        _write_bytes(bak, _read_bytes(path))
    write_encrypted(path, outer)



class Api:
    def __init__(self):
        self.path = None
        self.expanded = None

    def pick_save(self):
        try:
            win = webview.windows[0]
            res = win.create_file_dialog(
                webview.FileDialog.OPEN,
                file_types=('Inari Save (*.json)',))
            if res and len(res) > 0:
                return res[0]
        except Exception:
            pass
        return None

    def open_save(self, path):
        try:
            self.expanded = load_expanded(path)
        except Exception as e:
            return {"ok": False, "message": f"无法解密：{e}"}
        self.path = path
        return {"ok": True, **self._full_data()}

    def _full_data(self):
        d = self.expanded
        info = []
        if "playerData" in d:
            pd = d["playerData"]
            info.append(f"玩家 {pd.get('Name', '')}")
            info.append(f"地图 {pd.get('CurrentMap')} / 地点 {pd.get('CurrentSpot')}")
        if "timeData" in d:
            td = d["timeData"]
            info.append(f"第 {td.get('Day')} 天 · 时段 {td.get('Time')}")

        costs = []
        if isinstance(d.get("costData"), dict):
            for k, v in d["costData"].items():
                if k == "-1":
                    continue
                costs.append({"key": k, "name": cost_name(k),
                              "amount": v.get("HaveAmount"), "limit": v.get("Limit")})
        chars = []
        if isinstance(d.get("characterData"), dict):
            for k, v in d["characterData"].items():
                if k == "-1":
                    continue
                chars.append({"key": k, "name": char_name(k),
                              "favor": v.get("Favor"), "libido": v.get("Libido")})
        items = []
        if isinstance(d.get("itemData"), dict):
            for k, v in d["itemData"].items():
                if k == "-1":
                    continue
                items.append({"key": k, "name": item_name(k), "count": v.get("IHave")})
        skills = []
        if isinstance(d.get("skillData"), dict):
            for k, v in d["skillData"].items():
                if k == "-1":
                    continue
                skills.append({"key": k, "name": skill_name(k), "level": v.get("Level")})
        gallery = None
        if isinstance(d.get("galleryData"), dict):
            g = d["galleryData"]
            watched = sum(1 for v in g.values() if v.get("IsWatched"))
            gallery = {"watched": watched, "total": len(g)}

        return {
            "name": os.path.basename(self.path),
            "info": info,
            "costs": costs,
            "chars": chars,
            "items": items,
            "skills": skills,
            "gallery": gallery,
        }

    def _save(self):
        try:
            save_expanded(self.path, self.expanded)
            return True, None
        except Exception as e:
            return False, str(e)

    def _find(self, key, field):
        sec = self.expanded.get(field)
        if isinstance(sec, dict):
            return sec.get(str(key))
        return None

    def set_cost(self, key, amount):
        v = self._find(key, "costData")
        if v is None:
            return {"ok": False, "message": "未找到该货币"}
        v["HaveAmount"] = int(amount)
        ok, err = self._save()
        return {"ok": ok, "message": err or "已保存", "data": self._full_data()}

    def set_char(self, key, favor, libido):
        v = self._find(key, "characterData")
        if v is None:
            return {"ok": False, "message": "未找到该角色"}
        v["Favor"] = int(favor)
        v["Libido"] = int(libido)
        ok, err = self._save()
        return {"ok": ok, "message": err or "已保存", "data": self._full_data()}

    def set_item(self, key, amount):
        v = self._find(key, "itemData")
        if v is None:
            return {"ok": False, "message": "未找到该道具"}
        v["IHave"] = int(amount)
        ok, err = self._save()
        return {"ok": ok, "message": err or "已保存", "data": self._full_data()}

    def set_skill(self, key, level):
        v = self._find(key, "skillData")
        if v is None:
            return {"ok": False, "message": "未找到该技能"}
        v["Level"] = int(level)
        ok, err = self._save()
        return {"ok": ok, "message": err or "已保存", "data": self._full_data()}

    def set_all_items(self, amount):
        items = self.expanded.get("itemData")
        if not isinstance(items, dict):
            return {"ok": False, "message": "无道具数据"}
        for k, v in items.items():
            if k != "-1":
                v["IHave"] = int(amount)
        ok, err = self._save()
        return {"ok": ok, "message": err or "已保存", "data": self._full_data()}

    def set_all_skills(self, level):
        skills = self.expanded.get("skillData")
        if not isinstance(skills, dict):
            return {"ok": False, "message": "无技能数据"}
        for k, v in skills.items():
            if k != "-1":
                v["Level"] = int(level)
        ok, err = self._save()
        return {"ok": ok, "message": err or "已保存", "data": self._full_data()}

    def unlock_gallery(self):
        g = self.expanded.get("galleryData")
        if not isinstance(g, dict):
            return {"ok": False, "message": "无图鉴数据（图鉴在 gallery.json）"}
        n = 0
        for v in g.values():
            if not v.get("IsWatched"):
                v["IsWatched"] = True
                n += 1
        ok, err = self._save()
        return {"ok": ok, "message": err or f"已解锁 {n} 项", "data": self._full_data()}

    def unlock_content(self):
        cd = self.expanded.get("contentData")
        if not isinstance(cd, dict):
            return {"ok": False, "message": "无内容数据"}
        for v in cd.values():
            if isinstance(v.get("Datas"), dict):
                for dk in v["Datas"]:
                    v["Datas"][dk] = max(v["Datas"][dk], 1)
        ok, err = self._save()
        return {"ok": ok, "message": err or "已处理", "data": self._full_data()}

    def restore_backup(self):
        if not self.path:
            return {"ok": False, "message": "未打开存档"}
        bak = self.path + ".bak"
        if not os.path.exists(bak):
            return {"ok": False, "message": "没有备份文件 .bak"}
        _write_bytes(self.path, _read_bytes(bak))
        return self.open_save(self.path)



